 "content": "def transform(grid):
    """Restore masked cells by transposing the underlying grid pattern."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                out[r][c] = grid[c][r]

    # Where a mask overlaps its transpose, exploit repeated rows in the
    # periodic design, then propagate the recovered value across the diagonal.
    unresolved = [(r, c) for r in range(h) for c in range(w)
                  if grid[r][c] == 6 and out[r][c] == 6]
    for r, c in unresolved:
        if out[c][r] != 6:
            out[r][c] = out[c][r]
            continue
        best = None
        for rr in range(h):
            if rr == r or grid[rr][c] == 6:
                continue
            common = [(cc, grid[r][cc], grid[rr][cc]) for cc in range(w)
                      if grid[r][cc] != 6 and grid[rr][cc] != 6]
            support = len(common)
            if support >= 10 and all(a == b for _, a, b in common):
                if best is None or support > best[0]:
                    best = (support, grid[rr][c])
        if best is not None:
            out[r][c] = best[1]
            out[c][r] = best[1]
    return out
